    clip,
    shapeStyle,
    border,
    slotId,
    isVisible,
  ]);
}

/// Schema of a Wireframe type.
@immutable
sealed class SRWireframe {
  factory SRWireframe.fromJson(Map<String, Object?> json) =>
      switch (json['type']) {
        'shape' => SRShapeWireframe.fromJson(json),
        'text' => SRTextWireframe.fromJson(json),
        'image' => SRImageWireframe.fromJson(json),
        'placeholder' => SRPlaceholderWireframe.fromJson(json),
        'webview' => SRWebviewWireframe.fromJson(json),
        'embedded_content' => SREmbeddedContentWireframe.fromJson(json),
        final other => throw FormatException(
          'Unknown SRWireframe type: '
          '$other',
        ),
      };

  /// Defines the unique ID of the wireframe. This is persistent throughout the
  /// view lifetime.
  int get id;

  /// The position in pixels on X axis of the UI element in absolute
  /// coordinates. The anchor point is always the top-left corner of the
  /// wireframe.
  int get x;

  /// The position in pixels on Y axis of the UI element in absolute
  /// coordinates. The anchor point is always the top-left corner of the
  /// wireframe.
  int get y;

  /// The width in pixels of the UI element, normalized based on the device
  /// pixels per inch density (DPI). Example: if a device has a DPI = 2, the
  /// width of all UI elements is divided by 2 to get a normalized width.
  int get width;

  /// The height in pixels of the UI element, normalized based on the device
  /// pixels per inch density (DPI). Example: if a device has a DPI = 2, the
  /// height of all UI elements is divided by 2 to get a normalized height.
  int get height;
  SRContentClip? get clip;

  /// The type of the wireframe.
  String get type;

  /// A globally unique and stable identifier for this UI element, computed as
  /// the hash of the element's path. Used to correlate wireframes with RUM
  /// action events.
  String? get permanentId;

  Map<String, Object?> toJson();
}

int _int(Object? json, String where) => switch (json) {
  final int value => value,
  final double value when value == value.truncateToDouble() => value.toInt(),
  _ => throw _invalid(json, where),
};

double _double(Object? json, String where) => switch (json) {
  final num value => value.toDouble(),
  _ => throw _invalid(json, where),
};

String _string(Object? json, String where) => switch (json) {
  final String value => value,
  _ => throw _invalid(json, where),
};

bool _bool(Object? json, String where) => switch (json) {
  final bool value => value,
  _ => throw _invalid(json, where),
};

Map<String, Object?> _object(Object? json, String where) => switch (json) {
  final Map<String, Object?> value => value,
  _ => throw _invalid(json, where),
};

List<T> _list<T>(
  Object? json,
  String where,
  T Function(Object? json, String where) item,
) => switch (json) {
  final List<Object?> items => [
    for (final (i, value) in items.indexed) item(value, '$where[$i]'),
  ],
  _ => throw _invalid(json, where),
};

FormatException _invalid(Object? json, String where) =>
    FormatException('Invalid $where: $json');

bool _equals(Object? a, Object? b) {
  if (a is List<Object?> && b is List<Object?>) {
    if (a.length != b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (!_equals(a[i], b[i])) return false;
    }
    return true;
  }
  return a == b;
}

int _hash(Object? value) => value is List<Object?>
    ? Object.hashAll([for (final item in value) _hash(item)])
    : value.hashCode;
